## The Noble Fixes

```go
// Use RWMutex for better concurrency
mu sync.RWMutex

// Atomic stats
stats struct {
    Hits, Misses, LoadErrors atomic.Int64
}

// Fix Get fast path
func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && time.Now().Before(entry.ExpiresAt) && !entry.Loading {
        c.mu.RUnlock()
        c.stats.Hits.Add(1)
        return entry.Value, nil
    }
    c.mu.RUnlock()
    // ... continue with write lock
}

// Fix Set
func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = &CacheEntry{...}
}

// Fix GetMulti with WaitGroup
func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            if val, err := c.Get(ctx, k); err == nil {
                mu.Lock()
                results[k] = val
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

// Fix cleanup with proper locking
func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        if now.After(entry.ExpiresAt) {
            delete(c.data, key)
        }
    }
}
```

